// Rakit payload POST /api/v1/prakiraan-beban/ dari baris spreadsheet.
//
// Mendukung DUA layout sekaligus, dideteksi otomatis:
//
//   MELEBAR (layout Dashboard ROH) — jam jadi KOLOM, satu baris per tanggal:
//       |            |    0    |   0.3   |    1    | ... |  23.3   |
//       | 18-Aug-26  | 1,593.51| 1,546.94| 1,511.32| ... | 1,402.11|
//
//   MEMANJANG — satu baris per titik waktu:
//       | Tanggal    | Jam   | MW      |
//       | 2026-08-18 | 00:00 | 1593.51 |
//
// Juga menangani bentuk sel yang berbeda antar sumber: node Google Sheets
// mengirim STRING, sedangkan Extract From File (.xlsx) bisa mengirim ANGKA
// (serial Excel / pecahan hari) atau objek Date, karena di Excel tanggal dan
// jam disimpan sebagai angka.
//
// Hanya baris H dan H+1 yang dikirim — kurva hari lampau TIDAK ditimpa,
// karena histori itulah yang dipakai menghitung akurasi di FASOP.

const ZONA = 'Asia/Makassar';
const hariIni = DateTime.now().setZone(ZONA).toISODate();
const besok = DateTime.now().setZone(ZONA).plus({ days: 1 }).toISODate();
const DIIZINKAN = new Set([hariIni, besok]);

// Excel menghitung tanggal sebagai jumlah hari sejak 1899-12-30.
const EPOCH_EXCEL = Date.UTC(1899, 11, 30);

const FORMAT_TANGGAL = [
  'yyyy-MM-dd', 'dd/MM/yyyy', 'd/M/yyyy', 'dd-MM-yyyy',
  'dd-MMM-yy', 'd-MMM-yy', 'dd-MMM-yyyy', 'd-MMM-yyyy', 'dd/MM/yy',
];

// Pecahan pada LABEL jam ("0.3", "18.3"). Dua notasi dipakai di lapangan dan
// keduanya menunjuk slot yang sama: ".3" = jam.menit (00:30), ".5" = pecahan
// jam (setengah jam). Idem untuk kuartal: .15/.25 -> :15, .45/.75 -> :45.
// CATATAN: ini khusus LABEL. Sel jam numerik di .xlsx punya arti lain
// (pecahan HARI: 0.5 = 12:00) dan ditangani terpisah di menitDariSelJam().
const PECAHAN_KE_MENIT = {
  0: 0, 0.15: 15, 0.25: 15, 0.3: 30, 0.5: 30, 0.45: 45, 0.75: 45,
};

/** Ambil nilai kolom tanpa peduli besar-kecil huruf / spasi. */
function kolom(row, ...nama) {
  const peta = {};
  for (const k of Object.keys(row)) peta[k.trim().toLowerCase()] = row[k];
  for (const n of nama) {
    const v = peta[n.toLowerCase()];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return null;
}

/**
 * Angka dari sel, toleran dua konvensi pemisah yang dua-duanya muncul di
 * sheet PLN: "1,593.51" (ribuan koma) dan "1.593,51" / "1593,51" (desimal
 * koma). Aturannya: pemisah TERAKHIR adalah desimal, sisanya ribuan.
 * NaN kalau bukan angka.
 */
function angka(v) {
  if (typeof v === 'number') return v;
  if (v == null) return NaN;

  let s = String(v).replace(/[\s ]/g, '');
  if (s === '') return NaN;

  const posTitik = s.lastIndexOf('.');
  const posKoma = s.lastIndexOf(',');

  if (posTitik >= 0 && posKoma >= 0) {
    const desimal = posTitik > posKoma ? '.' : ',';
    const ribuan = desimal === '.' ? ',' : '.';
    s = s.split(ribuan).join('').replace(desimal, '.');
  } else if (posKoma >= 0) {
    // Hanya koma. "1,593" (tepat 3 digit di belakang, ada digit di depan)
    // hampir pasti ribuan; selain itu desimal ala Indonesia.
    const belakang = s.length - posKoma - 1;
    const banyak = s.split(',').length - 1;
    s = (banyak > 1 || (belakang === 3 && posKoma > 0))
      ? s.split(',').join('')
      : s.replace(',', '.');
  } else if (posTitik >= 0) {
    const belakang = s.length - posTitik - 1;
    const banyak = s.split('.').length - 1;
    if (banyak > 1 || (belakang === 3 && posTitik > 0 && /^\d{1,3}$/.test(s.slice(0, posTitik)))) {
      s = s.split('.').join('');            // "1.593" -> 1593
    }
  }
  return Number(s);
}

/** Menit dari objek Date. */
function menitDariDate(d) {
  // Sel waktu-saja dari SheetJS mendarat di tahun 1899/1900 dengan jam
  // tersimpan sebagai UTC — pakai getter UTC supaya tidak tergeser zona.
  return d.getUTCFullYear() < 1901
    ? d.getUTCHours() * 60 + d.getUTCMinutes()
    : d.getHours() * 60 + d.getMinutes();
}

/** Tanggal sel -> 'YYYY-MM-DD'. ISO, DD/MM/YYYY, 18-Aug-26, Date, serial Excel. */
function normalTanggal(v) {
  if (v == null || String(v).trim() === '') return null;
  // Date dari SheetJS dibuat pada tengah malam UTC; Asia/Makassar (+8) masih
  // jatuh di tanggal yang sama, jadi konversi zona di bawah aman.
  if (v instanceof Date) return DateTime.fromJSDate(v).setZone(ZONA).toISODate();

  if (typeof v === 'number') {
    return v > 20000                          // serial Excel (>= th. 1954)
      ? new Date(EPOCH_EXCEL + Math.floor(v) * 86400000).toISOString().slice(0, 10)
      : null;
  }

  const s = String(v).trim();
  for (const fmt of FORMAT_TANGGAL) {
    const d = DateTime.fromFormat(s, fmt, { zone: ZONA, locale: 'en' });
    if (d.isValid) return d.toISODate();
  }
  const iso = DateTime.fromISO(s, { zone: ZONA });
  if (iso.isValid) return iso.toISODate();

  const n = angka(s);
  return Number.isFinite(n) && n > 20000
    ? new Date(EPOCH_EXCEL + Math.floor(n) * 86400000).toISOString().slice(0, 10)
    : null;
}

/**
 * LABEL slot waktu -> menit sejak 00:00, atau null kalau bukan label waktu.
 * Dipakai untuk header kolom layout melebar ("0", "0.3", "18.3", "18:30")
 * dan untuk kolom Jam bertipe teks di layout memanjang.
 */
function labelKeMenit(v) {
  if (v == null) return null;
  const s = String(v).trim();
  if (s === '') return null;

  const jm = s.match(/^(\d{1,2}):(\d{2})/);          // "18:30", "18:30:00"
  if (jm) {
    const h = Number(jm[1]), m = Number(jm[2]);
    return h <= 23 && m <= 59 ? h * 60 + m : null;
  }

  const n = Number(s.replace(',', '.'));
  if (!Number.isFinite(n) || n < 0) return null;

  const jam = Math.floor(n);
  const menit = PECAHAN_KE_MENIT[Math.round((n - jam) * 100) / 100];
  return jam <= 23 && menit !== undefined ? jam * 60 + menit : null;
}

/**
 * Isi kolom Jam (layout memanjang) -> menit. Beda dengan labelKeMenit():
 * sel NUMERIK di .xlsx adalah pecahan HARI (0.5 = 12:00, 0.770833 = 18:30),
 * bukan notasi jam.menit.
 */
function menitDariSelJam(v) {
  if (v instanceof Date) return menitDariDate(v);
  if (typeof v === 'number' && v >= 0 && v < 1) return Math.round(v * 1440);
  return labelKeMenit(v);
}

/** true kalau kunci kolom terlihat seperti label slot waktu. */
function kunciSlotWaktu(k) {
  const s = String(k).trim();
  return /^\d{1,2}([.,:]\d{1,2})?$/.test(s) && labelKeMenit(s) !== null;
}

const rows = $input.all().map(i => i.json);
if (rows.length === 0) {
  throw new Error('Node sebelumnya tidak mengirim baris apa pun — periksa file/sheet yang dibaca.');
}

// ── Deteksi layout ────────────────────────────────────────────────────
// Melebar kalau baris pertama punya banyak kolom berlabel jam. Ambang 6
// supaya sheet memanjang (kolomnya cuma Tanggal/Jam/MW) tak pernah salah baca.
const kunciSlot = Object.keys(rows[0]).filter(kunciSlotWaktu);
const melebar = kunciSlot.length >= 6;

const data = [];
const dilewati = [];
const takTerbaca = [];

if (melebar) {
  // Kolom tanggal = kolom bernama Tanggal/Date, atau kolom pertama yang
  // BUKAN slot waktu (di sheet ROH header kolom ini sering kosong, dan
  // SheetJS menamainya "__EMPTY").
  const kunciTanggal = Object.keys(rows[0]).filter(k => !kunciSlotWaktu(k));

  for (const row of rows) {
    let tanggal = normalTanggal(kolom(row, 'tanggal', 'date'));
    if (tanggal === null) {
      for (const k of kunciTanggal) {
        tanggal = normalTanggal(row[k]);
        if (tanggal !== null) break;
      }
    }
    if (tanggal === null) continue;                  // baris judul / subtotal
    if (!DIIZINKAN.has(tanggal)) { dilewati.push(tanggal); continue; }

    for (const k of kunciSlot) {
      const mw = row[k];
      if (mw == null || String(mw).trim() === '') continue;   // sel kosong: wajar
      const menit = labelKeMenit(k);
      if (menit === null) { takTerbaca.push(String(k)); continue; }
      data.push({ tanggal, menit, mw: angka(mw) });
    }
  }
} else {
  for (const row of rows) {
    const mwMentah = kolom(row, 'mw', 'beban', 'beban (mw)', 'prakiraan');
    if (mwMentah == null) continue;                  // sel kosong: wajar, lewati

    const jam = kolom(row, 'jam', 'waktu', 'time');
    const menitKolom = kolom(row, 'menit', 'minute');
    if (jam == null && menitKolom == null) continue; // baris judul / kosong

    let menit;
    if (menitKolom != null) {
      const n = angka(menitKolom);
      menit = Number.isFinite(n) && n >= 0 && n <= 1439 ? Math.round(n) : null;
    } else {
      menit = menitDariSelJam(jam);
    }
    if (menit === null) { takTerbaca.push(String(jam ?? menitKolom)); continue; }

    const tanggal = normalTanggal(kolom(row, 'tanggal', 'date'));
    // Sheet satu hari tanpa kolom Tanggal -> pakai default server (hari ini).
    if (tanggal !== null && !DIIZINKAN.has(tanggal)) { dilewati.push(tanggal); continue; }

    const baris = { menit, mw: angka(mwMentah) };
    if (tanggal !== null) baris.tanggal = tanggal;
    data.push(baris);
  }
}

// Buang nilai MW yang tidak jadi angka — lebih baik kehilangan satu titik
// daripada mengirim NaN yang membuat seluruh kiriman ditolak server.
const bersih = data.filter(d => Number.isFinite(d.mw));
const mwRusak = data.length - bersih.length;

if (bersih.length === 0) {
  const unik = a => [...new Set(a)].slice(0, 5).join(', ');
  throw new Error(
    `Tidak ada baris prakiraan H/H+1 yang terbaca (layout terdeteksi: ${melebar ? 'MELEBAR' : 'MEMANJANG'}). `
    + `Tanggal yang dicari: ${hariIni} atau ${besok}. `
    + (dilewati.length ? `Tanggal lain yang ditemukan: ${unik(dilewati)}. ` : '')
    + (takTerbaca.length ? `Label jam tak terbaca: ${unik(takTerbaca)}. ` : '')
    + 'Periksa nama kolom (Tanggal/Jam/MW) atau header jam di sheet.'
  );
}

return [{
  json: {
    sumber: 'roh-sulbagsel',
    data: bersih,
    _layout: melebar ? 'melebar' : 'memanjang',
    _dilewati: dilewati.length,
    _jam_tak_terbaca: takTerbaca.length,
    _mw_rusak: mwRusak,
  },
}];
